<header class='header'>
    <div class='header__container'>
        <a href='/' class='header__logo header__default'>
        <img src='/comcash/img/logo.svg' alt='logo' />
        </a>
        <a href='/' class='header__logo header__christmas'>
        <img src='/comcash/img/new_year_img/logo.png' alt='logo' />
        </a>
